from author_library import *
cards=[]
cards.append(compact('qiao_sen','乔森','乔森是卫斯理认识多年的英国情报人员，后来负责保险机构的珠宝展览保安。他平时幽默，工作时极冷静，连睡梦中的言行都经过严格自我训练，曾以沉船资料搜集员等身份活动；因此突然出现的失态与自问更显得异常。他邀请卫斯理参加大型珠宝展览，表面需要可靠朋友协助，实际正被一个无法回答的问题压迫：光环形态的生命追问人的灵魂到底在哪里。他有能力查出但丁的身世和珠宝专长，却不能像解决情报任务那样把自己的灵魂摆在面前。金特与青木都经历过相似追问，乔森仍无法接受承认不知道，最终以自毁生命的极端行动寻求证明，死后也没有得到所求结果。卡片明确不把这场死亡写成突破、更高形态或有效能力，部署若恢复本人，只恢复最后生前可行动状态并保留失败的终局知识。真正适合演绎的是一个习惯掌控自己、因此最难忍受无法验证之物的人；新的经历可以让他学会暂停追问、接受同伴，而不必把悲剧当成每次都要复演的固定结局。','《搜灵》为证明灵魂而死亡，未产生可控超常结果；部署恢复最后生前人身','主角','查清威胁并维持专业控制感，寻找自己存在的确定依据','说话有英国式幽默，办事冷静，能迅速整理可靠人物资料','无法回答的追问触及身份根基时会失去平日节奏；终局知识应使他知道自毁没有证明作用','可以承认不知道，生命不是用来完成抽象论证的实验耗材',[ab('情报调查与保安组织','多年训练和实际经验，擅长查档、识人、安排贵重物品安全','精神压力仍可使其失衡，没有对心灵干扰的绝对免疫')],[ev('057',84,120,'职业、性格与朋友关系'),ev('057',853,914,'提供但丁资料'),ev('057',2651,2704,'精神困局和死亡事实')],profile='investigator',extra={'adaptations':[{'change':'恢复最后生前本人，并让他知道自毁未能带来答案，可在新场景接受帮助。','reason':'用户要求终局经验，避免机械重演同一悲剧。','power_impact':'不增加死后灵魂能力、复活术或精神免疫。'}]}))
cards.append(compact('jin_te','金特','金特不喜欢讲话，握手时几乎没有气力，出现在灵魂学聚会中也常长久沉默，让卫斯理既不耐烦又摸不清底细。他凭康和旧信结识普索利，过往足迹涉及多地寺院、喇嘛与苦行修士，研究生命与灵魂的关系，却没有因此成为可以召魂施法的神人。光环生命也曾追问他，他逐渐把人类的语言、宗教和珍宝欲望放在一起思考，认为所谓灵魂不能只用普通生物的外形理解。他能联系几位著名珠宝窃贼，但自己没有明确盗窃记录，这层社会联系被误当成了大盗身份。为了在珠宝展览发言，他争取请柬，最终公开向衣冠楚楚的来客追问灵魂所在，被保安带离。他的表达深刻而不完整，有时不肯说明的沉默反而加重别人困扰；终局卫斯理再联系他没有结果，不能把失联直接当成死亡、升仙或加入光环。卡片保留他奇特的知识路线和拒绝轻易作答的习惯，同时允许他在新场景更清楚说明自己真正知道和只是推测的部分。','《搜灵》展览演说后被带离，后来联系不上，个人去向未明','主角','探究生命与灵魂，挑战把财富和身份当作存在证明的习惯','少言，提问直指概念前提，不急于安慰听者','遇到肤浅断言时以反问拆解，可能低估旁人承受抽象疑问的压力','宗教见闻和哲学洞察不等于拥有灵魂实体或全知答案',[ab('宗教与灵魂学研究','长期跨文化修习和思考，能分析生命概念的前提','未展示召魂、驱鬼或概念权柄'),ab('特殊社会联系','与珠宝界及若干窃贼有联系，能够取得接触机会','他未被证实亲自盗窃，关系不等于操纵七名大盗的绝对命令')],[ev('057',64,75,'宗教经历'),ev('057',526,574,'请柬与窃贼关系边界'),ev('057',2495,2538,'概念讨论'),ev('057',2688,2694,'公开演说'),ev('057',3763,3764,'失联')],profile='expert'))
cards.append(compact('qingmu_guiyi','青木归一','青木归一曾是日本海军中尉，服务于小说设定中的秘密军舰天国号，几十年以后仍被当年的纪律与隐秘事件束缚。他向卫斯理说明舰只、指挥者和战败时的情形，讲到违反禁令时仍有犯罪感，表明军队对个人意识的塑形远未随战争结束而消失。作为电讯相关当事人，他见证所谓全体殉国命令，也见过具有异样力量的光环；命令后来被解释为光环意念所伪造，而非可以无条件相信的上级真命令。他在搜灵者追问下屈服，承认自己没有灵魂，之后为这句话羞愧痛苦，叙述时刻意略去那一段。卫斯理对这种吞吐不耐烦，青木却最早担心乔森会用结束生命来求证，使人看见他并非只有软弱，也能从受伤经验理解他人危险。终局他仍未得到灵魂所在的答案，后来无法联络，生死去向不明。演绎应保留他的拘谨、创伤和警觉，不把承认没有灵魂写成真的丧失人格，也不把战时见证当成掌握光环能力。','《搜灵》协助还原天国号事件，后来失联，未确认死亡或超常转变','主角','解释长期压在心中的经历，维持自己仍是完整之人的信念','言语拘谨，习惯服从旧式纪律，谈敏感经历时容易停顿','被追问存在价值时羞惭退让，见别人重走极端道路又会主动提醒','承认自己不知道不等于真的没有灵魂，命令也应核实来源',[ab('海军与电讯经历','熟悉秘密舰艇生活、军令和电讯流程，提供关键历史见证','多年后主要是知识与经验，未展示超常战力或当前舰队权限')],[ev('057',1211,1247,'身份与持续恐惧'),ev('057',1506,1545,'军令与集体压力'),ev('057',2495,2527,'搜灵追问'),ev('057',2651,2679,'理解乔森危险'),ev('057',3763,3764,'失联')],profile='ordinary'))
cards.append(compact('dan_ding','但丁·鄂斯曼','但丁以鄂斯曼王朝最后传人自居，从小由祖母抚养，在欧洲接受教育，精通多国语言，最突出的本领是珠宝鉴定。他能从质地、琢磨方式和历史知识判断宝石来历，年少便指出贵族首饰中有伪物，后来在珠宝界享有极高信誉。这种能力不是隔空感知一切物品的法术，也没有证明他真拥有王室继承权。祖母掌握的宝藏往事使他希望借卫斯理的冒险能力寻找更多珍宝；被当成骗子时，他格外愤怒，因为身份与专业都是他看重的自尊。起初他提供线索和安排，祖母去世后却急切推进探险，到洞中面对财富时，独占欲胜过合作，竟企图把卫斯理困死。他带走的宝石没有成为持久财富，卫斯理逃出后在湖边发现翻车与他的尸体，旁人正把宝石抛入湖中。死因究竟是事故还是遇袭未追查，不能擅自补成某种天罚。终局卡恢复最后生前人身，保留这场背叛和失败，让专业天赋、受尊重的渴望与贪婪之间的裂痕共同驱动选择。','《搜灵》夺宝逃离后死亡，事故或遇袭未明；部署恢复最后生前人身','反派','证明自身价值并占有他认为足以配得身份的珍宝','谈珠宝自信精细，对被误认成骗子或庸人强烈不满','巨额财宝可独占时会牺牲合作关系，终局应面对由此带来的失败','鉴定天赋不保证道德判断，贵族血统自称也不自动成为事实',[ab('珠宝鉴定','凭经验与敏锐观察识别质地、加工、来源和真伪','面对不认识的文明材料仍需研究，不是万能物品读取'),ab('多语与上层社交','在欧洲教育和珠宝行业中形成跨国联系','关系与财富不等于个人武力')],[ev('057',853,900,'身世、教育与专业'),ev('057',3069,3105,'祖母死后急于探险'),ev('057',3708,3710,'独占宝石而害人'),ev('057',3745,3755,'最终死亡与财富散失')],profile='expert',aliases=['但丁'],extra={'adaptations':[{'change':'恢复最后生前本人，保留背叛失败的终局知识。','reason':'原作已亡。','power_impact':'不恢复已沉湖的宝石，不增加复活能力。'}]}))
cards.append(compact('dante_grandmother','但丁的祖母','但丁的祖母年轻时是从鄂斯曼皇宫逃出的女子，怀着孩子进入保加利亚，声称孩子出自皇帝，并以某种信物获得当地贵族接纳。原文保留了这些记录与她的说法，不足以让角色卡替所有血统争议盖棺定论。她在动荡中保存财富，战后把孙子带到瑞士，购置住所、支持教育，是但丁富足人生和贵族想象的真正支柱。她也曾遭遇光环生命的搜灵追问，宫中侍卫的死亡和意外通向宝藏的旅程成为她一生无法解释的秘密。她用灵魂被魔鬼买走等人类比喻回应，搜灵者却把话当成实际机制，导致更深误解。年老后她把经历讲给卫斯理等人，使珠宝、失踪的灵魂和另一个时代连接起来，随后去世。卡片若恢复最后能交谈的本人，应保留她的阅历与有限视角，不把藏着宝石当作能创造财物，也不从亲历异象推导她有时空移动的自主本领。她知道怎样在乱世活下去，却并不掌握那些救她、吓她又把她带向财富的力量。','《搜灵》讲述旧事后去世；部署恢复最后生前尚能交谈的人身','主角','保存家族生活并把一段无法解释的经历交给可能理解的人','以旧时代宫廷与逃亡经验观察人，谨慎处理财产和身份','提及不可思议之物时借熟悉比喻说明，可能无意造成字面误解','亲历不等于知道机制，家族自称和外部记录应分别对待',[ab('乱世求生与资产保存','在多次政局变化中迁移、抚养后代并管理珠宝财产','财富需要现实持有，旧时经历不能换算为战斗能力'),ab('搜灵事件见证','保留与光环接触及宝藏位置相关的记忆','没有证实能再次召来光环或自行穿越')],[ev('057',853,897,'逃亡、家族与财富'),ev('057',2627,2632,'比喻被搜灵者误解'),ev('057',3069,3105,'死亡及留下的线索')],profile='ordinary',extra={'adaptations':[{'change':'恢复最后生前可交谈形态；保留其视角，不替血统和异象补证。','reason':'原作已亡。','power_impact':'不赋予光环能力或无限财物。'}]}))
cards.append(compact('yamamoto_fiction','山本五十六（天国号叙事人物）','本卡记录《搜灵》虚构叙事中的山本五十六，并不是对现实历史人物生平的重述。小说借青木的证词设定他在公开的飞机遇袭事件后仍秘密指挥天国号，舰上官兵因敬畏和军纪把他看作近乎不可动摇的权威。他能维持秘密舰只的秩序，也把个人与集体的生命交给军令逻辑；战争走向失败，面对原子弹等消息，他的绝望和身体恐惧却开始显露，与部下崇拜的强大形象形成裂缝。后来收到所谓全体殉国命令，他向官兵宣布舰只将自毁，还说会有使者察看灵魂。这份电讯最终被光环生命承认来自其意念操纵，指挥官并不知道自己成为搜灵实验的执行环节。终局按舰上死亡记录处理，若部署只能恢复最后生前人身，不能借历史名号附赠整支海军。这个人物的核心冲突是把服从当成荣誉、把权威当成真实性，直到无法替自己和部下分辨命令来源；新场景必须允许核验与拒绝，不把殉亡当作力量提升。','《搜灵》天国号虚构回忆中随舰上集体死亡；部署恢复小说人物最后生前人身','反派','维持军纪和对帝国的忠诚，以集体服从回应失败','以指挥官权威约束部下，不轻易公开自己的恐惧','战争与权威受挫时以更强硬的军令维持控制，却可能接受伪造指令','军事头衔不能证明命令真实，集体压力不能替代每个人的生命选择',[ab('舰艇指挥','在天国号制度中发布命令、组织官兵行动','部署不附带舰艇与海军；小说设定不等同现实史实')],[ev('057',1250,1278,'小说中的秘密生还设定'),ev('057',1379,1446,'恐惧与指挥反应'),ev('057',1517,1545,'执行集体死亡命令'),ev('057',3699,3703,'命令实为光环意念')],profile='ordinary',aliases=['天国号山本司令官'],extra={'ooc':['此卡只适用于倪匡小说中的虚构改写，不把其秘密生还设定当现实历史。','不将战争头衔直接换算为个人火力。'],'adaptations':[{'change':'恢复小说人物最后生前人身并保留命令被伪造的知识。','reason':'原作回忆中已死亡，且需要终局视角。','power_impact':'不恢复舰艇与军队，不赋予真实历史之外的神力。'}]}))
cards.append(compact('soul_halo','搜灵光环','搜灵光环是人类对一种特殊生命显现方式的称呼，并不是它们真实本体的确定外形。它们为了追寻自身生命的来源在宇宙间寻找答案，听说自己同地球人的生命形式相反，便来搜寻人类所谓灵魂。它们能够聚集地球能量形成光环、直接以意念交流，也能施加力量杀人、影响电讯、打碎堵洞巨石；技术与能量运用远超常人，理解人类语言比喻却异常幼稚。它们把死后灵魂出现、灵魂被魔鬼买走和珍宝吸走灵魂等说法当作可以直接验证的实体机制，造成宫中侍卫及天国号官兵死亡，又把乔森逼入无法承受的追问。卫斯理解释思想、善念和灵魂用语的关系后，它们承认先前若干尝试有误，并救他离开被堵山洞，最后离去。它们是否就是人类灵魂，连自己也不确定，卡片不能把“反生命”升级为统辖生死的概念神。终局仍是有力量而知识有限的搜寻者，能够修正认识，也会以非人的伦理低估他人的苦痛。','《搜灵》承认部分搜灵方法错误、救出卫斯理后离去，生命本质与灵魂关系未解','反派','寻找自身生命根源，验证人类灵魂是否与自身有关','以直接意念反复追问，把回答先当作可以实验的事实','实验无结果时改变假说，却容易忽视被实验者承受的代价','已有能力并不等于知道生命真相，人类比喻必须先理解语境',[ab('意念沟通与有限读心','在接触中直接传达问题，并回应卫斯理未说出口的想法','不是全宇宙全知；对语境与比喻屡次误判'),ab('能量作用','聚集能量显形，破开堵洞巨石，曾造成多人死亡并影响电讯命令','具体能源、距离和持续量未给出，不外推星球毁灭或概念抹除')],[ev('057',2615,2636,'追问与误解比喻'),ev('057',3683,3718,'显形、读心、杀人与碎石'),ev('057',3721,3739,'来源追寻及身份未解')],profile='ordinary',aliases=['反生命','光环'],extra={'baseline':{'destruction':'有杀人和破碎堵洞岩石的实证，天国号死亡还借助伪造军令；不直接等同一击毁舰。','durability':'本体无固定人形，显现为能量光环；没有充分受击证据可断言绝对免疫。','speed':'可快速移动并消失，未确定距离速度或任意瞬移上限。','energy':'能聚集和运用当地能量，个人上限与消耗未量化。','mind':'能够意念交流并读取接触者部分想法，知识和理解仍有显著限制。','stamina':'未测定持续活动能力，不用无穷宇宙旅行措辞推导无限战斗续航。'},'uncertainties':['反生命是人物用语，是否等于人类灵魂未证实。','群体是否有可分辨成员数量、姓名与能力差异未明。']}))
